{"content": "// Task CRUD and status transitions.
// Validates input, checks user existence, enforces a strict status
// machine, and integrates with permissions, cache, and audit.

import { findById, validateExists } from './users.js';
import { canDelete } from './permissions.js';
import { Cache } from './cache.js';
import { record, AuditEntry } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

// Allowed forward transitions; everything else is rejected.
const TRANSITIONS: Record<Task['status'], Task['status'][]> = {
  open: ['in_progress'],
  in_progress: ['done'],
  done: [],
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache = new Cache();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title || input.title.trim() === '') {
      throw new Error('Title is required');
    }

    // Both users must exist before a task can be created.
    validateExists(input.createdBy);
    validateExists(input.assignee);

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };

    this.tasks.set(task.id, task);

    const entry: AuditEntry = {
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    };
    record(entry);

    return task;
  }

  getTask(id: string): Task | null {
    // Check cache first, fall back to store.
    const cached = this.cache.get<Task>(id);
    if (cached) return cached;

    const task = this.tasks.get(id) ?? null;
    if (task) {
      this.cache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = TRANSITIONS[task.status] ?? [];
    if (!allowed.includes(status)) {
      throw new Error(
        `Cannot transition from ${task.status} to ${status}`
      );
    }

    task.status = status;

    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: id,
      timestamp: Date.now(),
    });

    this.cache.invalidate(id);
    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    if (!canDelete(task, userId)) return false;

    this.tasks.delete(id);

    record({
      action: 'delete',
      userId,
      taskId: id,
      timestamp: Date.now(),
    });

    this.cache.invalidate(id);
    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId
    );
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
